                values: new object[,]
                {
                    { 45, "عبد الله مكسور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما جرى في هذه الحكاية يقع كل يوم، عندما أقول كل يوم فإني أعني ذلك، من الساعة الرابعة فجرًا حتى السادسة مساءً، في أوقات لا يلتفت فيها العالم إلى شيءٍ سوى نفسه.\nيحدث هذا خارج نشرات الأخبار، وخارج اللغة الكبيرة. في ساعات الانتظار التي لا تُحسب من العمر لكنها تستهلكه. لهذا فما حدث في الحكاية ليست لحظة استثنائية، بل واحدة من لحظات كثيرة تتشابه إلى حدِّ التطابُق والقسوة، فيما تختلف فقط بأسماء العابرين وأيام الأسبوع.\nكل ما يرد في الحكاية مقصود ومدروس كجزء من لعبة الشاباك، إنها رواية على شكل وقوف طويل أمام بابٍ مفتوحٍ نصف فتحة، تساؤل صامت عمَّا إذا كان العبور بحثًا عن معنى، أم إضافة اسمٍ آخر إلى سجل الامتيازات؟\nحكاية تبدأ بتباطؤ مقصود؛ لأن بعض الحكايات لا تحتاج افتتاحية صاخبة، وإنما تحتاج شجاعة الاعتراف الأول بأن الدخول ليس بسيطًا، وأن الكتابة نفسها عبء، وأن حمل هذا العبء هو الشرط الوحيد للمضي قُدمًا نحو عبورٍ مؤجَّل.\nعبد الله مكسور، روائي وصحفي عربي من مواليد سوريا، صدرت له سبعة أعمال روائية وكتاب «هندسة المعنى» في الصحافة والإعلام. يعمل في الصحافة منذ عام 2007م، كما عمل في المسرح البلجيكي، ولديه خبرة طويلة تمتد لأكثر من عقدين في العمل التلفزيوني والتدريب على تقنيات الكتابة الإبداعية والفنون الصحفية، تُدرَّس أعماله ضمن مساقات الكتابة الحديثة في العديد من الجامعات.", "/images/products/9789777956000.webp", "9789777956000", "عبور مؤجل", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 46, "خالد الجابر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في رسالتها الأخيرة، ومن سريرٍ تتأرجح فوقه الأنفاس بين وداعٍ بطيء واستدعاءٍ مُلحٍّ للذاكرة، تُسطِّر ماري مجدولين، الراهبة السابقة والممرضة الأمريكية الموفدة للتبشير، اعترافها الأشد صفاءً، والأكثر وجعًا.\nعبر مرايا الاسترجاع، تُعيد تركيب رحلتها التي شقَّت بها البحر نحو سواحل الخليج والجزيرة العربية؛ إلى أرضٍ لا تُبدِّل الاتجاهات فحسب؛ بل تُعيد صياغة الإنسان من الداخل.\nهناك؛ حيث تبدو الموروثات حدودًا قاطعة، وتُختبَر الرحمة على حافة القسوة، وتشتبك الطقوس مع الأسئلة، تكتشف ماري أنَّ الغريب ليس القادم من بعيد؛ بل ذلك الذي ينهض في أعماقنا حين تُنزع الأقنعة، ويُدفَع القلب إلى مواجهة صورته بلا مواربة.\n\"الإرسالية\" ليست حكاية سفرٍ من ميناءٍ إلى ميناء؛ بل ملحمة عبورٍ داخلي، من يقينٍ مُستعار، إلى يقينٍ مُكتسَب بالألم، مِن إيمانٍ يَسكُن، إلى إيمانٍ يُفتِّش، مِن صمتٍ يُعَدُّ فضيلةً إلى صمتٍ قد يتحوَّل إلى خيانة.\nد. خالد الجابر\n-باحث وأكاديمي وأديب وروائي ومؤلف مسرحي قطري.\n-يُعد من أبرز الأصوات الفكرية في قطر والخليج.\n-شغل مناصب أكاديمية وإعلامية بارزة، منها أستاذ الاتصال السياسي بجامعة قطر، ورئيس تحرير صحيفة The Peninsula، إلى جانب قيادته لمراكز بحثية وثقافية.\n-يحمل درجة الماجستير من الولايات المتحدة، والدكتوراه من المملكة المتحدة، إضافة إلى دبلومات علمية من جامعات: جورجتاون وستانفورد وفوردهام الأمريكية.", "/images/products/9789777955973.webp", "9789777955973", "الارسالية", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 47, "محمد مصطفي منصور", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب يُقدِّم للقارئ أشعار ابن عطاء الله السكندري، الذي عاش في القرن السابع الهجري، وتوفي مطلع القرن الثامن، وكانت أشعاره مُتفرِّقة في بعض كتبه.\nويجمع الكتاب شِعر «ابن عطاء» على وجهٍ ملائمٍ يليق بصاحب الشِّعر ومكانته، وبالأفكار التي اشتمل عليها، وبالقضايا التي يعالجها.\nوقد اجتهد مُحقِّق الكتاب في جمع شعر «ابن عطاء» من الأصول المخطوطة لبعض كتبه؛ للوقوف على حقيقة ما ورد بها من شِعر، وملابسات كل نَصٍّ منه، والتمكُّن من تحقيق تلك النصوص تحقيقًا علميًّا دقيقًا، وفق قواعد التحقيق العلمية، وضبط ألفاظ تلك النصوص، حتى تظهر الأشعار للقارئ بصورة جيدة، واستبعد المحقق الطبعات المتاحة بالأسواق لكتب «ابن عطاء» لكثرة ما ورد بها من أخطاء وتحريفات تحول بين القارئ للشعر وبين إدراك ما ورد به من أفكار بصورة صحيحة.\nوالكتاب إضافة حقيقية للمكتبة العربية، خاصة الأدب الصوفي المصري؛ إذ إنه يُعدُّ أول ديوانٍ مُحقَّقٍ لشِعر ابن عطاء الله السكندري.\n***\nد. محمد مصطفى منصور، أستاذ الأدب العربي المتفرغ بكلية دار العلوم، جامعة الفيوم. عمل محررًا وباحثًا بمجمع اللغة العربية بالقاهرة في الفترة من 1983م حتى 1991م، وشارك في تحرير مجالس المجمع ومؤتمره ومجلته. وضع الأسس الفنية لدراسة ملامح الأدب الصوفي المصري في كلية دار العلوم بجامعة الفيوم. أصدر نحو تسعة عشر كتابًا، منها: نداء المؤمنين في القرآن الكريم (1998م)، النثر الفني في عصري صدر الإسلام وبني أمية (1998م)، شرح قصيدة أبي مدين «ما لذة العيش إلا صحبة الفقرا» لابن عطاء الله السكندري (2001م)، الوقاية من العنف: قراءة تحليلية في الحديث النبوي الشريف (2021م).", "/images/products/9789777955935.webp", "9789777955935", "ديوان ابن عطاء", null, 175m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 48, "مصطفي الفقي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس سهلًا أن يعترف الإنسان بأخطائه أو سلبيات حياته، خاصة حين يكون قد حقَّق ما يضعه في مصاف المشهورين والمؤثرين في الحياة، وأضحى ملء السمع والبصر كما يُقال؛ لذلك فمجرد «التفكير» يُعد شجاعة كبيرة، أما الانتقال من منطقة الفكرة، إلى مساحة الفعل والكتابة، فهي جسارة لم يتَّسِم بها سوى قليلين.. ومن هؤلاء الجسورين الدكتور مصطفى الفقي، المفكر والكاتب والأديب والدبلوماسي والسياسي الذي طبَّقت شهرته الآفاق، ولم يكُن متحدثًا حصيفًا وراصدًا دقيقًا للأحداث فحسب، بل كثيرًا ما شارك في صناعتها، وحرَّك بفكره ورؤاه الكثير منها.\nوفي هذا الكتاب يقدم د. الفقي مادة ثرية كثراء حياته، ممتعة كطلاقة لسانه وتفرُّد أفكاره، متنوعة كتنوع خبراته وتشعُّب علاقاته، فيجد القارئ نفسه في بُستانٍ مُبهج، يتنقَّل فيه بسلاسةٍ ورشاقةٍ من الدبلوماسية إلى العمل الأكاديمي، ومن النشاط الإعلامي إلى التمثيل البرلماني، ومن الحياة الإنسانية البسيطة إلى الحياة السياسية المعقدة، فضلًا عن تناول كثير من القضايا الفكرية والإنسانية والثقافية والسياسية في مصر والوطن العربي بل والعالم، وككل كتب الدكتور مصطفى الفقي، فإن القارئ على موعد مع فيض فكري وإنساني، يمتاز برشاقة الأسلوب، وتنوع الأفكار، وبراعة الطرح والتناول.", "/images/products/9789777955898.webp", "9789777955898", "صفحات مطوية اعترافات ومراجعات", null, 400m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 49, "جو كالاجان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو كان شريكك في التحقيق… ليس إنسانًا؟\nفي تجربة حكومية غير مسبوقة، تُجبر رئيسة المباحث «كات فرانك» على العمل مع «لوك»، ذكاء اصطناعي تجريبي بهيئة بشرية، لاختبار مستقبل العمل الشرطي، وذلك أثناء التحقيق في سلسلة من حالات الاختفاء الغامضة.\n«كات» تعتمد على الحدس والخبرة الإنسانية، و«لوك» لا يثق إلا في الأرقام والخوارزميات.\nلكن هذه القضية ليست عادية؛ كاميرات مراقبة متوقفة، آثار رقمية ممحوّة، وملفات بلا أي خيط واضح.\nهل هناك مَن يتلاعب بكل ما هو رقمي.. بلا أثر؟\nبينما تتقدم التحقيقات، تكتشف «كات» أن هناك قاسمًا مشتركًا واحدًا بين جميع المفقودين، قاسمًا لا تراه الخوارزميات، لكن يلتقطه حدسها فورًا: ابنها «كام».\nوعندما يختفي «كام» بدوره، يتحول التحقيق إلى سباق مع الزمن، وإلى مواجهة شخصية مع الماضي، ومع سؤال أخطر: هل يمكن للذكاء الاصطناعي أن يفهم الإنسان عندما تصبح حياته على المحك؟\n«في غمضة عين» رواية مشوقة تمزج بين الجريمة والخيال العلمي، عن الفقد والأمومة، وعن صراع الذكاء البشري مع الذكاء الاصطناعي، وعن ذلك الحد الفاصل الدقيق بين العبقرية.. والجنون.\nعن المؤلفة:\nجو كالاجان كاتبة بريطانية من برمنغهام، عملت لسنوات في مجالات القيادة والإدارة العامة، وبالتوازي اهتمت بأسئلة المستقبل وتأثير الذكاء الاصطناعي على المجتمع والعمل وهو ما ينعكس بوضوح في عالم روايتها. في عام 2024 فازت \"في غمضة عين\" بجائزة Theakston Old Peculier – Crime Novel of the Year (أفضل رواية جريمة في بريطانيا)، كما حصدت أيضًا جائزة CWA John Creasey (New Blood) Dagger لعام 2024، ووصلت إلى قوائم الترشيح لجوائز أخرى، لتصبح واحدة من أبرز الروايات البوليسية في السنوات الأخيرة.\nترجمة   :- حسام شاكر", "/images/products/9789777955850.webp", "9789777955850", "في غمضة عين", null, 500m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 50, "عرفة عبدة على", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سريات أسرة محمد علي\nيتناول الكتاب تاريخ إنشاء أشهر القصور المَلَكية التي شهدها أسرة محمد علي، ويفرد الكاتب لكل قصر أو سراي فصلًا خاصًّا يلقي من خلاله الضوء على ظروف نشأتها وقيمتها المعمارية والحضارية من حيث تاريخ تشييدها ومَن سكنها من أفراد الأسرة العلوية، ثم المصير الذي آلت إليه.\nولا يكتفي بتقديم وصف لهذه الآثار الفنية البديعة، وإنما يتطرّق إلى رصد الأبعاد الاجتماعية لتلك الحقبة المثيرة للجدل من خلال «حياة القصور» وما يدور فيها من أحوال الملوك والأمراء والبرنسيسات والهوانم، ومن يعاونهم من وصيفات وأغوات وخدم وطباخين وشماشرجية ومسلواتية، وغيرهم.\nعرفه عبده علي، كاتب صحفي وعضو اتحاد الكُتَّاب، نُشِر له العديد من الدراسات والمقالات بالصحف والدوريات المصرية والعربية، متخصص في تاريخ اليهود في مصر وتاريخ القاهرة ومعالمها، عمل مساعدًا لمدير مكتبة المعهد الفرنسي للآثار الشرقية بالقاهرة، اتخذت وزارة الخارجية المصرية قرارها بتعميم كتبه عن يهود مصر على كل السفارات والقنصليات المصرية بالخارج. أبرز مؤلفاته: \"تهويد عقل مصر\"و\"ملف اليهود في مصر الحديثة\" و\"قـراءة في الفكـر الإسـرائيلي المعاصر\"و\"القاهـرة في عصـر إسماعيل\" و\"الإسكندرية في عصرها الذهبي\"و\"مملكة الأقطاب والدراويش\"و\"رمضان في الزمن الجميل\"و\"حكايات مصرية من زمن العز القديم\".", "/images/products/9789777955904.webp", "9789777955904", "سرايات اسرة محمد على", null, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 51, "نهي داود", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"جثا المحقق على ركبتيه بجوار الجثة المنكفئة على أرض المكتب يتأمّل الجرح النافذ على الجبهة والثقب الذي توسّط الصدغ والدماء المتخثرة من حولها وتساءل: \"معقولة تكون انتحار؟\".\n***\nتبدأ الرواية بجثة منكفئة وتساؤل حائر وعيون محدّقة، وتنتهي بالحقيقة.. وبين البداية والنهاية تتشابك الأحداث، ما بين  حب مستحيل، ومعاملات مالية مشبوهة، ودوافع غير أخلاقية، وقلوب معلقة بالأمل، وقاتل مجهول، ومطر كاشف!\nنهى داود كاتبة مصرية ولدت في إنجلترا عام 1975، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".", "/images/products/9789777955478.webp", "9789777955478", "جريمة في ليلة ممطرة", null, 235m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 52, "ابن جلجل", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُعَدُّ هذا الكِتَابُ  وَثِيقَةً مُهِمَّةً في تَارِيخ العُلُومِ وتَطَوُّرِ حَـرَكَةِ التَّألِيف والتَّرْجَمَة في القَرْنِ الرَّابِع الهجري/العاشِر الميلادي ، الذي يُعَدُّ  بحَقٍّ العَصْـرَ الذي ازْدَهَرَت فيه الحـَضَارَةُ الإسْلامِيَّـةُ ونَمَت، وبَلَغَت غَايَتَهَا من الإنْتَاجِ الوَاسِع في شَتَّى مَيَادِين العُلُوم والآدَاب. ولَعَلَّ مَيْزَةَ هذا الكِتَاب الأُولَى التي جَعَلَت له قِيمَةً عِلْمِيَّـةً خاصَّةً ونَصًّا قَدِيمًا له خَطَـرُه في تَارِيخ العِلْم ، أنَّ مُؤَلِّفَهُ يَعْتَمِدُ في ما رَجَعَ إليه من مَصَادِرَ على تَـرَاجِمَ عَـرَبِيَّـة لأصُولٍ لَاتِينِيَّـةٍ تَارِيخيَّـة.\nوالمـَوْضُوعُ الذي اخْتارَهُ مُؤَلِّفُنَا هو «طَبــَقَاتُ الأَطِبَّاء والحـُـكَمَاء» ، وهو وإنْ كان أوَّلَ أنْدَلُسِـيٍّ ألَّفَ في هذا المـَوْضُوع ، إلَّا أنَّـنـَا نَجِدُ أنَّ غَيْرَه من المـُؤَلِّفِين في المـَشْـرِقِ الإسْلَامِي قد سَبَقُوه إلى هذا النَّوْعِ من التَّألِيف ، بما أنَّ أقْدَمَ مَصْدَرٍ  بين أيْدِينَا  الآن عَرَضَ لتَـرَاجِم الأطِبَّاء  وهو «كِتَـابُ الفِهْرِسْت» الذي ألَّفَه أبو الفَـرَج محمَّد بن إسْحَاق النَّدِيم في شَعْبان سنة 377هـ/987م، أي في نفس السَّنَة التي ألَّفَ فيها ابن جُلْجُل كِتَـابَه .\nواعْتَمَدَ ابن جُلْجُل في جَمْعِ مَعْلُومَاتِه على ما تَوافَر في الأنْدَلُس من الكُتُب التي عَرَضَت لهذا المـَوْضُوع . وبِمَا أنَّ اللُّغَةَ الأصْلِيَّة لأهْلِ هذه البِلَاد هي اللُّغَة اللَّاتِينِيَّـة ، فقد تُـرْجِمَت عنها بعضُ المـُؤَلَّفات التَّارِيخِيَّة إلى العَـرَبِيَّـة في القَرْنِ الرَّابِع الهِجْرِي/العَاشِر المِيلَادِي الذي عَاشَ فيه ابن جُلْجُل، لَعَلَّ أهَمَّهَا «كِتَـابُ بَاوْلُوس أورُوسْيُوس Paulus Orosios» - الذي يَذْكُرُه ابن جُلْجُل دَائِمًا باسْم «هُـرُوشْيُوش» -  واعْتَمَدَ عليه في ما يَخُصُّ الأطباء اليونان واللاتين.\nواعْتَمَدَ كذلك على «كِتَـاب يُـرُونُم التُّـرْجُمان» واسْمُه باليُونَانِيَّة «خرُونِيقُون» والذي تُـرْجِمَ إلى العَـرَبِيَّـة باسْمِ «القَرْوَانِقَة».\nتحقيق     :- فؤاد سيد\nاعدها للنشر :- أيمن فؤاد سيد", "/images/products/9789777955775.webp", "9789777955775", "طبقات الأطباء والحكماء", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 53, "سهير السمان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"لقد كان الحب هو ما كنت أحتاجه وشعرت به في هذا المنزل حين ضمّنا جميعًا\" ربما كان الخطأ الوحيد الذي ارتكبته هذه المرأة التي تمثل شريحة واسعة من نساء الوطن العربي أنها كانت تحلم بوطن بلا قهر، تحاصرها العادات والتقاليد بـ \"العريس المناسب\"، وتحرق الحرب الأهلية ما تبقى من كرامتها وكيانها، وتسرق الكيانات الإرهابية منها الأمل في غدٍ بلا وجع.\nتكشف لنا سهير السمان في روايتها عن أثر التحولات السياسية والاجتماعية على أوضاع مجموعة من النساء، وبينما تبحث كل واحدة فيهن عن نصيبها من الحب والحياة، يَعُدْنَ فيَلْتَقيْنَ خلف «جنازة واحدة لموت كثير» في وطن ممزق بالصراعات، وتديُّن زائف متشح بالسواد.\nسهير رشاد السمان، روائية وناقدة يمنية تقيم في القاهرة. حاصلة على الماجستير في النقد الأدبي من جامعة القاهرة. صدرت لها ثلاث مجموعات قصصية، هي: «موعد آخر» و«جزء من النص مفقود» و«يحدها من الشمال»، وكتاب نقدي بعنوان: «الرواية اليمنية في الألفية الثالثة.. التقنيات السردية ورؤية العالم». حاصلة على جائزة رئيس الجمهورية في القصة القصيرة باليمن.", "/images/products/9789777955249.webp", "9789777955249", "جنازة واحدة لموت كثير", null, 220m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 54, "ولاء كمال", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "راوٍ يعاني الأرق والذعر من انهيار العالم، مؤلف موسيقيّ عبقري يتحول إلى قاتل دموي في عصر النهضة، شخصياتٌ حية وأخرى تمردت على صفحات الكتب، وكلبٌ يستمع للموسيقى الكلاسيكية.. تُرى كيف يجمع ظلام الليل كل هؤلاء؟\nفي مغامرته الفنية الأكثر جرأة يصحبنا ولاء كمال في ليلتين مليئتين بالغرابة والدهشة، ليقدم لنا رؤيته للعالم والإنسان عبر ليلةٍ عجيبة يقضيها الراوي بمحطة وقود. بينما في زمنٍ آخر، وتحديدًا في إيطاليا القرن السادس عشر، نعيش أحداث ليلةٍ أخرى دامية وذات آثار مروعة، ترويها لنا محاضر التحقيقات وشهادات من عاصروها، لنخوض مع صفحات الرواية وشخوصها مغامرةً وجودية ونفسية مذهلة، ندرك خلالها أن الليل ليس فقط ما نعيشه.. ولكن ما يسكن بداخلنا.\nولاء كمال، كاتب وروائي ومترجم مصري. صدرت له عن الدار المصرية اللبنانية أربع روايات، وكتاب \"أيامي مع كايروكي: حكاية جيل أراد أن يغير العالم\". رُشحت روايتاه \"القداس الأخير\" و\"كوش كو\" لجوائز أدبية محلية وإقليمية، كما صدرت له عدة كتب مترجمة. درس الترجمة والإعلام والإخراج السينمائي، وحصل على درجة الماجستير في الأدب العربي من الجامعة الأمريكية بالقاهرة.", "/images/products/9789777955881.webp", "9789777955881", "مادريجال الليل", null, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 55, "طارق عز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"تنفتح بوابة السر للمرة الوحيدة في ألف عام،\nفإن دخلت المنسية لمولد النور،\nمن الدمع ولدت ومن الدم تعود،\nسُفك الدم وانبثقت الذاكرة،\nواستيقظت التي كانت من قبل الزمان\".\n***\nهناك قوى لا تستيقظ.. بل تتذكر لتطالب بحقها المسلوب.\n\"سيدة الأبدية\" رواية عن المنسيين الذين كُتب عليهم أن يحملوا كلمات المصير. تدور أحداثها في ليلة واحدة تكشف أسرارًا بعمر الكون.. من حكايات النيل إلى لعنات السماء، نخوض رحلة ملحمية تستحضر صراعات النور والظلام، في عالم يعيد كتابة تاريخه.\nشخصياتها تمضي على حافة الحقيقة، حيث لا خلاص بلا مواجهة، ولا معرفة بلا نار.\nففي النهاية.. الدم هو الذاكرة، والغضب هو البوابة.\nطارق عز.. روائي وقاص ومترجم مصري، صانع محتوى متخصص في الكتابة والقراءة. يعمل بالطيران المدني، نُشرت له قصص قصيرة في مجموعات قصصية مشتركة، مثل \"اعترافات\"، و\"اليوم الأخير\". حاصل على جائزة أفضل قصة قصيرة في مسابقة\"iRead\" لعام 2021، والقائمة القصيرة لنفس الجائزة 2022. وقد صدرت له ترجمة رواية \"ينابيع واكولا\" الحاصلة على جائزة أفضل رواية قصيرة 2013، ونالت روايته الطويلة الأولى «أسفار مريم المحرمة» استحسانًا وإقبالًا جماهيريًّا واسعًا، وتصدرت قوائم الأكثر مبيعًا، وتُعد «موت مع إيقاف التنفيذ» مجموعته القصصية الأولى، و«سيدة الأبدية» العمل الأدبي الثالث له.", "/images/products/9789777955874.webp", "9789777955874", "سيدة الابدية", null, 275m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 56, "نهلة كرم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا أحد يعلم ماذا يحدث في الداخل، نساء يصرخن، يضحكن، يبكين، كل منهن جاءت إلى المكان من أجل شيء لا يعلمه أحد سواها، يترك العمود سيئ السمعة على أجسادهن كدمات، ويحررهن من كدمات أخرى لا يراها أحد.\nفي استوديو مخصص لرقص \"الپول\" تجتمع نساء غريبات، كل منهن جاءت لسبب مختلف عن الأخرى، لكن حياتهن جميعًا تغيرت تمامًا، فكيف يمكن لعمود أن يقلب حياتهن؟\nنهلة كرم: كاتبة وروائية مصرية، من مواليد القاهرة سنة 1989. تخرجت في كلية الإعلام جامعة القاهرة. صدرت لها ثلاث روايات: \"على فراش فرويد\"، \"المقاعد الخلفية\" الفائزة بجائزة ساويرس، و\"خدعة الفلامنجو\" التي وصلت إلى القائمة الطويلة لجائزة كتارا. كما صدرت لها مجموعتان قصصيتان: \"أن تكون معلقًا في الهواء\"، و\"الموت يريد أن أقبل اعتذاره\"، اللتان وصلتا إلى القائمة القصيرة لجائزة ساويرس.", "/images/products/9789777955713.webp", "9789777955713", "دراما كوين", null, 275m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 57, "حسين حمودة", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يضم هذا الكتاب مجموعة من الكتابات حول فن الرواية؛ تستكشف في قطاع منها بعض الظواهر التي تناولتها أعمال روائية.. وتتوقف، في قطاع آخر، عند بعض التناولات والمعالم الجمالية لعدد من الروايات.. وتعرض، في قطاع ثالث، لمجموعة من القضايا التي طُرحت، وما زالت تُطرح، حول الرواية من حيث مسيرتها التاريخية، أو تكوينها، أو حضورها، أو تأثيرها..\n***\nيجمع بين هذه الكتابات أنها جميعًا تتصل بالنوع الروائي، وأنها كلها تُمثِّل خطوات على طريق واحد لمقاربة هذا النوع الأدبي، وأنها بأكملها صدرت عن كاتب واحد ظل يسعى إلى الإصغاء لما تقوله، وكيف تقوله، النصوص الروائية.", "/images/products/9789777955867.webp", "9789777955867", "طريق الى الرواية ظواهر وقراءات وقضايا", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 58, "احمد عثمان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لعنةٌ تخرج من بين القبور، تصيب كل من يقترب من قبره أو يقرأ كتابه المدفون تحت تراب القاهرة الفاطمية، إنه عبد الله الحظرد، نديم الخليفة الأموي، الوليد بن عبد الملك، وأمهر سحرة العرب الذي وضع كتابه «العزيف» قبل أن يموت مقتولًا على يد أحد خلصائه من الجن، لكنه، وبينما يلفظ أنفاسه الأخيرة، استطاع قراءة تعويذة أحكمت قبضتها على «جِني الغابر» وحبسته بين دفتي الكتاب.\nفي هذه الرواية+ الأسطورة، يتأجج الصراع بين ثلاث عائلات، الكاشف، والرملي، والعاصي، تريد كل واحدة منهن العثور على كتاب «العزيف» والاستحواذ عليه، في صراع يقتات على دمٍ مسفوح لأشخاص ارتبطت أقدارهم بهذا الكتاب فلم يعد لهم إرادة في دفع قدر ملعون ولعنة أبدية.\nأحمد عثمان\nروائي وكاتب سيناريو، مواليد القاهرة 1982. تخرّج في كلية الهندسة – قسم العمارة.\nصدر له عدد من الأعمال الروائية، من بينها \"القديس\" و\"3110\"، وسلسلة حلمي مهران.\nألّف فيلم قبل الأربعين، ومسلسل روحي فيك، وحصل على جائزة القلم الذهبي لأفضل سيناريو عام 2025.", "/images/products/9789777955843.webp", "9789777955843", "الوارث", null, 350m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 59, "نهاد ابو القمصان", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقدم هذا الكتاب تجربة المؤلفة في التعامل مع القضايا منذ وصولها إلى مكتبها، وكيفية دراسة كل قضية على حدة، والبحث وراء السطور من أجل التوصل إلى الحقيقة، قبل طرحها أمام القضاء في قاعة المحكمة.\nست عشرة قضية ضمها الكتاب، اختارتها الأستاذة نهاد أبو القمصان من مئات القضايا التي عملت عليها، حاولت المؤلفة في كل حكاية منها أن تضع صوت المظلوم في المقدمة، وأن تقاوم محاولات النفوذ والمال لتأكيد مسار العدالة.\nوتوضح المؤلفة أنها لا تقدم للقارئ مجرد حكايات؛ وإنما تكشف كيف يمكن للمحامي أن يكون شاهدًا على المجتمع، مدافعًا عن المظلوم، وناقلًا لصوت الحقيقة في مواجهة النفوذ والظلم.\nوتسعى إلى أن يكون الكتاب مرشدًا للطلاب والباحثين عن كيفية التعامل مع القضايا عامة، والجنائية تحديدا، وأن يكون- كذلك- مصدر وعي للقراء العاديين، حتى لا يقعوا في أخطاء قد تقودهم إلى ساحات القضاء.\nنهاد أبو القمصان.. محامية مصرية، عضو المجلس القومي لحقوق الإنسان، وأمين عام المجلس القومي للمرأة سابقًا، وخبيرة بالأمم المتحدة والبنك الدولي، ومديرة بيت الخبرة النوعي والقانوني، ورئيسة المركز المصري لحقوق المرأة. مقدمة برامج تلفزيونية.  حاصلة على جوائز وطنية ودولية عديدة آخرها ‎وسام الاستحقاق المدني  عام 2020 والذي تسلمته من ملك إسبانيا.", "/images/products/9789777955836.webp", "9789777955836", "ما وراء الاوراق", null, 240m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 60, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه الرواية تأخذنا \"عبد المجيد\" إلى الأرض التي تتصدَّر المشهد الحالي وتتجه إليها الأبصار..\nالأرض التي تحتاج تميمة من الأمل.. الأرض التي كانت يومًا، وستبقى دومًا أيقونة خيرٍ وجمال..\n‏رحلة تمتد منذ عام 1969م وحتى نهاية 2023م ، تكشف فيها عن موروثات وعادات ما كانوا يتحدثون عنها يومًا..\n‏عن صراعات سياسية واجتماعية اضطرت الكثيرين في النهاية إلى مغادرة البلاد قسرًا وجبرًا..\n‏لكن رغم الألم والفساد..\nرغم الموت والدمار.. تبقى القصص حيَّة تُروَى وتُخلَّد على صفحات التاريخ.. وفي النهاية التمائم إلى أرضها لا بد وأن تعود، فمهما تباعدت الخطى.. اللقاء حتمي.. والتاريخ لا يَنسى..\nالظلم دومًا نهايته الزوال!\nنور عبد المجيد. شاعرة وروائية. شغلت منصب مساعد رئيس تحرير مجلة \"روتانا\"، ولها ديوان شعر \"وعادت سندريلا حافية القدمين\". وروايات منها: \"رغم الفراق\"، و\"أريد رجلًا\"، و\"أنا شهيرة\"، و\"أنا الخائن\"، و\"أنتِ مني\" و\"كان\"، وتم تحويل رواياتها إلى أعمال درامية، وتُرجمت بعض أعمالها إلى اللغة السويدية.", "/images/products/9789777955720.webp", "9789777955720", "عودة التمائم", null, 275m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 61, "يوسف عز الدين عيسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"هدأت نفسه قليلًا، ولكنه عاد يشعر بقسوة الوحدة عندما قام الرجل واختفى داخل الكهف. ملأت السعادة قلبه عندما نظر فرأى على مقربة من الكهف مدينة ذات عمائر وقصور وقلاع. ظل ناظرًا إليها مبهورًا.\nلم تكن هذه المدينة هنا، فكيف ظهرت بغتة؟ أنا لم أتحرك من مكاني، فهل كانت المدينة تسير نحوي؟ هذا مستحيل. ماذا حدث إذن؟\".\n***\nتنتمي هذه المجموعة القصصية إلى العالم الأسطوري الحالم، الذي يبدأ بحدث واقعي مدهش، وينتهي بنا إلى نهايات غير متوقعة، فيضفي على كل ما هو واقعي سحرًا خاصًّا ورمزية غاية في التشويق.\nفقصص مثل: \"نور الشفق، القطار، ليلة العاصفة\"، تعبر عن النفس البشرية بكل أحلامها وإخفاقاتها وضآلة الإنسان بالنسبة لأسرار الكون، مهما أوتي من علم. أما \"الجمجمة\" -التي لم تنشر من قبل- فيجمع فيها د. يوسف عز الدين عيسى بين الأمراض النفسية وتأثيرها على الجسد.\nد. يوسف عز الدين عيسى، جمع بين العلم والأدب في أعلى مستوياتهما، فهو أديب له عالمه الخاص، حصل على جائزة الدولة التقديرية في الأدب وغيرها من الأوسمة الرفيعة. تأثر أدبه بروح العصر فعبر عن الإنسان وحلل النفس  البشرية بكل نوازعها وأحلامها وصراعاتها بأسلوب شيق يتأرجح بين الحلم والواقع، الخيال والحقيقة. كسرت رواياته الحاجز التقليدي للرواية العربية، وهو من أول رواد الواقعية السحرية فيها.", "/images/products/9789777955812.webp", "9789777955812", "خارج الكهف", null, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 62, "سهير عبدالحميد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«فلاح خرسيس».. كانت هذه الجملة الشهيرة تتردَّد على لسان الباشا صاحب العِزبة، وهو يحمل الكُرباج بيده ويهوي به على ظهور الفلاحين المحنية بفعل القهر! صورة رسَّختها الدراما المُسيَّسة في أذهاننا، وهي تصنع في عقولنا ذلك الارتباط الشَّرْطي المعيب بين البكوات والباشوات من جانب، وبين الإقطاع والاستغلال الاقتصادي والسياسي من جانب آخر. صحيح أن ألقاب البكوات والباشوات كانت كالسلعة تُباع وتُشتَرى، لكن هناك رجال حصلوا عليها عن جدارة، ودون سعي منهم أو طلب. رجال قدَّموا لهذا البلد ما ظل كشجرةٍ وارفةِ الظلال، أصلها ثابت وفرعها في السماء.\nإن هذا الكتاب يتناول تاريخ ما أهمله التاريخ: سِيَر رجال كانت إنجازاتهم أعلى من الألقاب، وفي ثنايا حكاياتهم وجبة دسمة من تاريخ مصر جغرافيًّا وسياسيًّا واقتصاديًّا واجتماعيًّا، وجرعة مكثفة من تاريخ الحجر والبشر، الزمان والمكان، وتصحيح لمفاهيم مغلوطة رسَّختها حركة 23 يوليو التي شابها عوار سياسي وإنساني واقتصادي وقانوني. وكان العوار الأكبر - في تقديري - هو محاولتها تزييف الوعي الجمعي عَبْرَ مَن يحلو لي تسميتهم «ترزية التاريخ».\nسهير عبد الحميد، كاتبة صحفية، مدير تحرير «الأهرام»، وباحثة في التاريخ. صدر لها: قصور مصر، إسكندرية من تاني، اغتيال قوت القلوب الدمرداشية، على عتبة المقام، سلسال الباشا، ناحوم أفندي، يهود الظاهر.", "/images/products/9789777955782.webp", "9789777955782", "بكوات وباشوات", null, 330m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 63, "أحمد الشهاوي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلةٌ عمليةٌ ومُلهِمةٌ في أسرارِ الإبداعِ كما عاشها ودوَّنها سبعة عشر كاتبًا وكاتبةً من مشاهير الأدب العالمي.\nلا تُقَدَّم الكتابةُ هنا بوصفها موهبةً غامضةً حكرًا على قلةٍ مُختارةٍ، بل كمسارٍ يمكنُ تعلُّمُهُ وصقلُه وتطويرُهُ عبر استراتيجياتٍ واضحةٍ ونصائح مجرَّبة. تجمعُ المترجمة والشَّاعرة والأكاديمية سارة حامد حوَّاس خلاصاتِ تجارب هؤلاء الكُتَّاب، وتعيدُ تقديمَها إلى القارئ ، لتضعَ بين يديه مفاتيح للكتابةِ المؤثِّرةِ ..كيف تبدأ؟ كيف تستمرُ؟ كيف تتغلبُ على الخوفِ والتردُّد وحبسة الكتابة؟ وكيف تُحوِّلُ الأفكار المُبعثرة إلى نصٍّ ينبضُ بالمعنى؟\nما يجعل هذا الكتاب مختلفًا هو أنه لا يكتفي بسردِ تجارب الآخرين، بل يُحفِّزُك على النظرِ إلى نفسِكَ ككاتبٍ مُحتملٍ، ويطرحُ أسئلةّ تجعلك تعيدُ التفكيرَ في علاقتكَ بالكتابةِ، ولماذا تكتبُ، ولمَن.\nإنه كتابٌ يشبهُ ورشةَ كتابةٍ مفتُوحةً، ومرشدًا صامتًا يرافقُكَ خُطوةً بخطوةٍ.\nد. سارة حامد حوَّاس، مدرس بقسم اللغة الإنجليزية، بآداب المنصورة، مترجمة وشاعرة. صدر لها في الترجمة والشِّعْر عدة كتب، منها: \"ثُقب المفتاح لا يَرَى.. عشرون شاعرة أمريكية حائزات على جائزتيْ نوبل وبوليتزر\"، الذي وصل إلى القائمة القصيرة لجائزة جابر عصفور للترجمة، و\"ولاؤهم للروح.. عشرون شاعرًا أمريكيًّا حائزًا على جائزة بوليتزر\"، و\"في قلبي قارة.. عشرون شاعرة وشاعرًا أفرو‑أمريكيًّا\"، وترجمة كتاب \"قبلة رُوحي\".. مختارات من شعر أحمد الشهاوي صدرت في كلكتا بالهند، وديوانها الشعري \"جبل على كتفي\".\nتحرير وتقديم :- احمد الشهاوى", "/images/products/9789777955829.webp", "9789777955829", "اسرار الكتابة", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 64, "شريف عرفة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس كل صوت يُسمع.\nكل ما أراده (جلال) هو معرفة من يخاطبه، ولم يدرِ أن الطريق إليه يمر عبر طقوس دموية، وعوالم افتراضية، وطائفة دينية، وكيانات واعية.. وسط أحوال تذوب فيها الفواصل بين اليقين والوهم، وبين البشر ومن هم غير ذلك.\nرواية تتتبع رحلة عقل إلى حدوده القصوى..\nحيث الجواب موجود.. لكنه ينتظرك في مكان غير موجود.\nد. شريف عرفة\nالكاتب الأكثر مبيعًا في علم النفس الإيجابي.\nحاصل على ماجستير علم النفس الإيجابي التطبيقي، وماجستير\nفي إدارة الأعمال، وبكالوريوس طب وجراحة الأسنان.\nتُرجمت مؤلفاته للإنجليزية وحاز جوائز وتكريمات عديدة.", "/images/products/9789777955744.webp", "9789777955744", "صاحب الصوت الأزرق", null, 250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 65, "ميخائيل عماد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في حفل توقيع روايته الجديدة بفندق الماريوت٬ يفاجئ الكاتب الشهير (يوسف سليمان التركي) بزائر خاص من الماضي٬ كيان شيطاني يتخذ شكل (فرانز كافكا). وقبل أن يهرب منه يوسف يحتجزه كافكا في مصعد الفندق ليخبره أن الليلة ليست ليلة عادية٬ وانما ليلة الحساب ودفع الثمن للعقد الذي أبرماه معًا منذ 15 عامًا٬ وأن يوسف سيمضي ليلة خاصة سوداء٬ مُطارد من قِبل كل ذنوبه، لأن هناك عدوًا خفيًّا له حصل على امتياز كتابة ليلة كاملة من حياته، وأن كل ما سيكتبه سيحدث.\nتدور الرواية في ثلاث ليال٬ الليلة الرئيسية في حاضر ٬2025  وليلتان من العام 2010. نرى خلالها كيف بدأت العلاقة بين يوسف وذلك الشيطان، وكيف تخلى الكاتب المغمور عن مبادئه أمام الغواية، وكيف سقط في بئر سحيقة مطاردًا أحلامه، وكيف سينعكس ذلك على ليلة خاصة جدًّا من حاضره، سيهرب فيها من ماضيه وذنوبه، وسيطارد كاتبًا مهووسًا يريد تدميره، في ليلة مليئة بالندم والدماء، والألغاز، والبحث عن الخلاص، والنبش في الماضي.\nميخائيل عماد، صيدلاني وروائي مصري من مواليد 1995، صدرت له أربع روايات حتى الآن٬ من ضمنها (أثر اليعسوب) و(الخريف في بالم تاون) واستطاع لفت الأنظار عن طريق صوت أدبي خاص وأفكار غير معتادة. كما شارك في كتابة عدة مسلسلات وأفلام وبرامج مثل (الدحيح) و(في الحضارة).", "/images/products/9789777955690.webp", "9789777955690", "ليل القاهرة السرى", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 66, "حسن عبد الموجود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "باب الأبراج لم يكن مجرد ورقة أسلِّمها لرئيس قسم \"بريد القراء\" في جريدتنا، كنت مقتنعًا أكثر من أي شخص آخر بأن الأبراج لها تأثيراتها الحقيقية علينا، على حياتنا وعلاقاتنا بالآخرين ومصائرنا. أقرأ كثيرًا من المراجع في الأبراج، محاولًا فهم حركتها، وطريقة حساب علاقاتها المتشابكة، كيف ترضى عنا، وكيف تنقلب علينا؟ كيف تكون محايدة، وكيف تتدخل في شؤوننا كعاصفة تقتلعنا من جذورنا؟\n***\n\"حروب فاتنة\" واحدة من أكثر المجموعات القصصية نجاحًا، فقد حظيت بمراجعات ومقالات ودراسات متنوعة، وفازت بجائزة يوسف إدريس للقصة القصيرة، وعدَّها النقاد واحدة من قمم القصة المصرية والعربية، وترجمت مجلة \"بانيبال\" بعض قصصها إلى الإنجليزية والإسبانية، ووصفتها بأنها \"لا تُنسى\".\nحسن عبد الموجود، كاتب مصري، صدرت له روايتان، وخمس مجموعات قصصية، وأربعة كتب في السيرة والصحافة الأدبية. حصل على جائزة دبي للصحافة الثقافية، وجائزة يوسف إدريس للقصة، وجائزة ساويرس للرواية، وجائزة معرض القاهرة الدولي للكتاب لأفضل مجموعة قصصية. تُرجمت أعماله إلى الإنجليزية والإسبانية والفرنسية والألمانية.", "/images/products/9789777955706.webp", "9789777955706", "حروب فاتنة", null, 150m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 67, "جبران خليل جبران", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يضم الكتاب مجموعة من الحكم والتأملات التي وضعها جبران من أجل محاربة الآفات الاجتماعية كالغش والخداع والنفاق والحسد، وهي الأمراض التي فرضها التنافس غير الأخلاقي بين البشر، في أثناء سعيهم من أجل المادة. ويقدم المؤلف وجبة فلسفية عميقة تغلفها لغة شاعرية رقيقة في تلمسها المعنى من أجل إيصاله إلى القلوب، وفي تصيدها لغة رمزية تحرص على تبسيط الحكمة وتقريب الفلسفة. إن هذا الكتاب على صغر حجمه قد حوى بين دفتيه آراء جبران في موضوعات شتى كالأخلاق والشعر والتصوف ونظرية الجمال، وهي كلها موضوعات لا تزال تشغل حيزا في تفكير الإنسان المعاصر، وقد عالجها جبران هنا بعمق فلسفي يلامس النفس البشرية ويتسلل إلى أعماق وجدانها .", "/images/products/9789777955485.webp", "9789777955485", "رمل وزبد", null, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 68, "صلاح دياب", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "طالبني بعض الأهل والأصدقاء والمقربين بتوثيق قصة حياتي، وكلما مرَّ الوقت ازداد الإلحاح، ومعه ازدادت حيرتي! وأمام هذه الحيرة تدفقت على الخاطر جملة من الأسئلة، أولها هو: هل سأكتب بنفسي؟ وبالفعل اتخذت قراري بعد تفكيرٍ عميق: نعم، سأكتب بنفسي. تلاه سؤال ثانٍ أصعب: هل أستطيع أن أسرد كل شيءٍ؟\nلا يهم.. المهم أنني سأكتب.. هذا كان القرار.\nلذلك لن تجد في هذه المذكرات شخصًا مثاليًّا. فقد كانت لي أخطاء وحماقات، كما كانت لي أفعال أفخر بها. غامرت حتى الثمالة، ودفعت ثمن مغامراتي كاملًا. مررت بنجاحات وإخفاقات. تحمَّلت اختبارات قاسية. حصلتُ على الكثير من المنح، كما تعرضت للكثير من المِحَن.\nفي رحلتي تعرَّفت على بشر من كل نوع. بعضهم فرحت بدخوله إلى حياتي، وآخرون فرحت بخروجهم من دائرتي، ومنهم مَن ظل في المساحة الرمادية، فأجده بجواري حينًا، وأبحث عنه ولا أجده أحيانًا أخرى.\nقد تكون هذه المرة الأولى التي أتحدث فيها عن نفسي، فأنا لست محترفًا في فن الكلام، لكنني.. وللمرة الأولى - وربما الأخيرة - أجدني بحاجة إلى البوح بما يعرفه بعض المقربين منِّي، وبما لم يعرفه أحد من قبل.", "/images/products/9789777955324.webp", "9789777955324", "مذكرات صلاح دياب", null, 470m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 69, "زينب عفيفي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\" بعض الكلمات تظل عالقة في ذهني، وحين أكتب تعليقًا على رواية أعجبت ببطلها يأتي ناقصًا في المعنى، ولا تأتي مشاعري كما أشتهي، ويبقى إحساسي ناقصًا يحتاج إلى أن يخرج بطل الرواية عن النص ويضمني بالمعنى الناقص في واقعي\".\n***\n\"السماء لا تمطر حكايات\".. رواية عن امرأة تكتشف أن الكلمة قد تُسرق، لكن الروح لا تُنتزع.\nفي عالمٍ يُكافأ فيه مَن يتحدث بصوتٍ أعلى، تبقى \"حنان\" مجرد ظل في حياة الأدب. تكتب، وتحلم بنشر روايتها الأولى.. حتى تأتي الخيانة من أقرب الناس إلى روحها: مَن أحبَّته واعتقدت أنه الوحيد الذي يؤمن بأنها كاتبة. تستيقظ على كابوس نشر روايتها الأولى باسمه، وتتحول من \"كاتبة حالمة\" إلى \"ملهمة مجهولة\".\nتقف \"حنان\" أمام قرار مصيري: هل تستعيد أفكارها؟ أم تستعيد نفسها؟ أم تمتهن بيع الأفكار للروائيين المفلسين.\nزينب عفيفي.. كاتبة وروائية، صدر لها ثمانية عشر عملًا ما بين قصص قصيرة وكتب وروايات منها: \"شمس تشرق مرتين\" و\"خمس دقائق\" و\"أهداني حبًّا\" و\"أحلم وأنا بجوارك\" و\"معك تكتمل صورتي\"، و\"عزيزي المستبد\"، و\"عملية تجميل\".. تُرجمت بعض قصصها إلى اللغة الإنجليزية عن دار نشر أسترالية وبعضها تُرجم إلى اللغة الإيطالية. لها العديد من المقالات الأسبوعية في الأدب والثقافة. حازت جائزة أفضل صفحة في مجال الكتب في الصحافة الثقافية المصرية عام 2015م. حصلت على جائزة يوسف إدريس في دراسة بحثية نقدية عن أدبه.", "/images/products/9789777955799.webp", "9789777955799", "السماء لا تمطر حكايات", null, 280m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 70, "عزت القمحاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إننا، ببساطة مدهشة آسرة، أمام موت معلن منذ الصفحات الأولى، ندرك في الآن ذاته أنه مجازات حياة لا تقل احتشادًا بالصخب والكتمان والغرام.\nصبحي حديدي - من كلمته على غلاف \"غرفة ترى النيل\" 2004.\nيقدم لنا القمحاوي في \"البحر خلف الستائر\" تنويعاته المتفردة على ما سميته بتجربة الخروج العربي. وهي تجربة ثرية في الأدب المصري.\nصبري حافظ عن «البحر خلف الستائر» جريدة التحرير 2014.\nبخفة الثعبان الذي يخاف ويخيف ـ يستعير القمحاوي لغة المدينة ليواجهها بأقوالها وأساطيرها نازعًا عنها عباءتها التي لا تستر عورة.\nعبدالرحمن الأبنودي ـ عن «مدينة اللذة» في كتابه النثري «آخر الليل».\n“مدينة اللذة”، عمل فذ، وعلامة فارقة في فن القص العربي. نص بالغ الدقة والإحكام والحساسية.\nفتحي أبو رفيعة ـ من كتابه «تفكيك السرد».\nمن اليأس تأتي هذه الكتابة. كل لذة يجب أن تؤخذ ضمن حدود اللحظة. كل جمال في حقيقته سراب..\nعناية جابر ـ عن مدينة اللذة، جريدة السفير 2009.", "/images/products/9789777955607.webp", "9789777955607", "ثلاثية الغربة", null, 285m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 71, "ميرنا الهلباوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل كان سر نجاح كوكو شانيل هو عمر أفندي؟\nثم ما علاقة مزارع الياسمين في دلتا مصر بسجون هتلر النازية في ألمانيا؟\nولماذا استقل الدكتور سيجموند فرويد قطار الإسكندرية- القاهرة متجهًا إلى جاردن سيتي في مصر؟\nوما العامل المشترك بين الفنان الإسباني سلفادور دالي وأمينة الفلاحة المصرية البسيطة؟\nوهل يمكن تخيل ارتباطٍ وثيقٍ بين الفرنسي چاستون ماسبيرو رئيس مصلحة الآثار المصرية والمقاومة الفلسطينية؟\nفيليب باخ بطل هذه الرواية المثيرة هو الوحيد الذي لديه إجابات عن هذه الأسئلة الغريبة.\nرواية مستوحاة من أحداث حقيقية لرجل عادي ذي أثر مذهل، تحتار في تصنيفه هل هو بطل أم أناني لدرجة تثير الغيظ؟\nكان فيليب باخ يصر على معاندة أقداره وتجاهلها لينتهي به الأمر في رحلة حياة جنونية وخطيرة عكس كل ما يتمناه من الهدوء والحب والسعادة.\nميرنا الهلباوي: كاتبة وإعلامية مصرية. عملت في الصحافة، وترشحت للقائمة النهائية لجائزة الصحافة العربية. عملت مذيعة في راديو NRJ ومراسلة استقصائية مع شبكة BBC للتحقيقات الوثائقية. لديها ثلاثة إصدارات من الأكثر مبيعًا: \"مر مثل القهوة حلو مثل الشوكولا\" و\"كونداليني\" و\"تنذكر ما تنعاد\". وهي مؤسسة حملة Connecting Gaza ومنظمة Connecting Humanity غير الهادفة للربح.", "/images/products/9789777955577.webp", "9789777955577", "محاولات فاشلة للهروب من القدر", null, 250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 72, "شريف شعبان", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقدم المؤلف في هذا الكتاب قراءة جديدة في دراسة تاريخ مصر القديمة، يتناول خلالها هذا الإرث العظيم من البرديات التي كتبها المصري القديم وتركها على جدران معابده وأهراماته لنعرف منها آدابه وتفاصيل حياته اليومية من دين وزواج وطقوس دفن، إلى جانب ما رصدته هذه البرديات من نشاط الغزاة الذين نهبوا خيرات مصر، ويكشف لنا عن أطوار الصعود والهبوط خلال بوابات الزمن التي مرَّت بها الحضارة المصرية القديمة، وقد نجح في عقد خيط يضم عددًا من الوقائع يجمعها رابط واحد هو الإنسان المصري وحضارته الموغِلة عبر آلاف السنين.\nتثبت هذه \"البوابات\" بما لا يدع مجالًا للشك أن الحضارة المصرية لم تكن مجرد حضارة مادية فقط تمثَّلت في بناء الأهرام وتشييد المعابد، بقدر ما كانت أيضًا حضارة روحية تجلّت فيها قيم المعتقد بالحياة الآخرة ورسَّخت فكرة العدالة (الماعت) التي صارت لبِنة أساسية في البناء الأخلاقي للمصريين القدماء.\nد. شريف شعبان، كاتب وخبير في الآثار المصرية، ومؤرخ فني. حاصل على الدكتوراه في الفنون المصرية القديمة. عمل محاضرًا لمادة تاريخ الفنون بجامعة القاهرة. صدرت له عدة روايات وكتب ومترجمات، منها: الأسقف ومناظرها عبر العصور (2011)، المآدب والولائم في مصر القديمة وحضارة الإغريق (2016)، يهود مصر القديمة (2012)، النبي المفقود أخناتون (2022)، موسوعة رحلة إلى الشرق القديم: مصر وجيرانها في 3 آلاف (2024)، أشهر خرافات الفراعنة (2025)، وروايتين: بنت صهيون (2015)، و 3 نبوءات سوداء (2017).", "/images/products/9789777955683.webp", "9789777955683", "بوابات الزمن", null, 230m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 73, "عمار على حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يضم هذا الكتاب سبعين حكاية خرافية، يتداولها الناس في قرى مصر ومدنها، عمن يستحضرون الجان، أو ما يأتيه السحرة والمشعوذون والعرافون من قارئي الكف والتاروت والفنجان والمَندل وضاربي الودَع والمهتمين بحسابات النجوم والفلك، والساعين خلف الكنوز المطمورة، والمبالغين في تصوير كرامات الأولياء والقديسين، والمعتقدين في التمائم والحروز والطلاسم، ومَن يشغلهم الخوف من الحسد والعفاريت، وتجذبهم حكايات عمَّا بعد الموت، ويصدقون النبوءات القديمة، وأولئك الذين يؤمنون بالفيوضات الروحية التي تجلب الطاقة الإيجابية، ومَن يتمسكون بأرقام وأشياء جالبة للحظ.\nلقد سمعت من أهل قريتي هذه الحكايات العجيبة صغيرًا، وتعاملت معها كمادة خام لعمل أدبي، قاصدًا ألا أتركها في سيلانها وجريانها على الألسنة هائمة عائمة، إنما راسية بين سطور مكتوبة، هي في خاتمة المطاف روايتي لهذه الحكايات العجيبة المدهشة المملوءة بالشغف والرعب والإيهام والإلهام والأمل.\nسبعون حكاية عن عوالم خفية، لعل القارئ يكتشف بها ومعها ثراء مخيلة أهلنا الذين سردوا هذه الحكايات عبر آلاف السنين، ويكتشف في رحابها قدرة جيلنا على الاستفادة منها، وتقديمها سِفرًا من أسفار عجائبيتنا وغرائبيتنا الساحرة.\nعمار علي حسن، أديب ومفكر مصري، أصدر اثنين وستين كتابًا، نصفها أعمال أدبية هي روايات ومجموعات قصصية ودواوين شعرية ومسرحية وسيرة ذاتية ونصوص عابرة للأنواع، ونصفها الآخر كتب في الاجتماع السياسي، والنقد الأدبي والثقافي، والتصوف، والفكر. أُعدت حول رواياته وقصصه عشرون رسالة جامعية داخل مصر وخارجها، وصدرت عنها كتب ودراسات نقدية، وتُرجمت بعض أعماله العلمية والأدبية إلى عدة لغات، ونال عنها جوائز كبرى.", "/images/products/9789777955676.webp", "9789777955676", "الأرانب الحجرية", null, 375m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 74, "احسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"وعاد زوجي من إحدى سهراته «الرجالي» بعد منتصف الليل.. وأيقظني بقبلاته.. وأخذ يروي لي تفاصيل سهراته مع أصدقائه.. ونمنا.\nوفي الصباح، وعندما كنت أضع يدي في جيوبه لأنقل حاجياته من بدلة إلى بدلة تعلقت عيني بمنديله..\nلقد كان في المنديل بقعة كبيرة من آثار أحمر شفاه، تلمع أمام عيني كأنها جذوة من نار..وتصاعدت الدماء إلى رأسي.. أحسست أن الدنيا تدور بي.. وأن كتلًا من الظلام تتجمع أمام عيني حتى لم أعد أرى شيئًا..\".\nولد أول يناير 1919 بالقاهرة، تخرج في كلية الحقوق عام 1942.  بدأ حياته كاتبًا سياسيّا ورئيسًا لتحرير مجلة روزاليوسف التي أسستها والدته فاطمة اليوسف. فجّر قضية الأسلحة الفاسدة التي استخدمت في حرب فلسطين.  تقلد عددًا من المناصب الصحفية كان آخرها رئيسًا لتحرير ولمجلس إدارة مؤسسة الأهرام، وبعدها تفرغ للكتابة حتى وفاته 11 يناير 1990.  أنتج المئات من الروايات والمجموعات القصصية التي تحوّل معظمها إلى أعمال سينمائية وإذاعية وتليفزيونية. حصل على العديد من أرفع الأوسمة والجوائز وشهادات التقدير المحلية والعالمية.", "/images/products/9789777955645.webp", "9789777955645", "زوجة أحمد", null, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 75, "ممدوح محمد الدماطي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتناول هذا الكتاب قصة خروج بني إسرائيل من مصر، وهي واحدة من أبرز الأحداث المثيرة للجدل في السرد الديني والتاريخي والثقافي، خاصة ما يتعلَّق بسؤال من أكثر الأسئلة جدلًا وغموضًا في الدوائر التاريخية والدينية: مَن هو فرعون موسى؟ وهو السؤال الذي تتولَّد منه أسئلة أخرى، منها: هل كان هذا الفرعون ملكًا مصريًّا من الأسرات المحلية، أم إنه كان من سلالة أخرى تمامًا؟ وما هي الظروف الحقيقية التي رافقت خروج بني إسرائيل من مصر؟ هذه الأسئلة وغيرها شغلت الباحثين والمؤرخين والمهتمين، وحتى الأفراد العاديين، على مر العصور، وفي هذا الكتاب محاولة للإجابة عنها، من خلال جهد بحثي قدَّمه المؤلف مُستندًا إلى خبرة أكاديمية رصينة، نابعة من تخصُّصه في مجال الآثار والحضارة المصرية القديمة، وإلمامه العميق بتحليل النصوص القديمة وفهم الدلالات الثقافية والتاريخية المرتبطة بالأحداث، فضلًا عن دراسة ميدانية مُستمدَّة من معرفته الدقيقة باللغتين المصـرية القديمة، والقبطية، وقد ظهر ذلك بوضوح في مقابلاته بين النصوص المختلفة بهدف تقديم رؤية علمية مدعومة بالأدلة التاريخية واللغوية، وهو ما يُثري محتوى الكتاب ويعزِّز مصداقيته العلمية.\nممدوح محمد الدماطي، وزير الآثار الأسبق، أستاذ الآثار المصرية القديمة منذ عام 2006م. شغل عددًا من المناصب الأكاديمية وغير الأكاديمية. نشر 15 كتابًا، و30 بحثًا علميًّا في الدوريات العلمية الدولية والمحلية، ويرأس تحرير سلسة «مصريات» بالهيئة المصرية العامة للكتاب منذ مارس 2021م. فاز بعدد من الجوائز والأوسمة، أبرزها: وسام «فارس» من رئيس جمهورية إيطاليا (2004م)، جائزة الدولة للتفوق في العلوم الاجتماعية (2010م)، جائزة الدولة التقديرية في العلوم الاجتماعية (2024م).", "/images/products/9789777955669.webp", "9789777955669", "موسي علية السلام", null, 190m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 76, "نهى داود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا تعرفون عن الحب؟\nهو قرص من عسل أو ورد على سياج بعيد؟\nوماذا إذا التقى الحبيبان بعد فراق طويل؟ فراق لم يقضِ على حبهما بل أججه في قلبيهما كجمرة مشتعلة تحت الرماد.\nيا لروعة اللقاء الثاني.. وأحلامه.. ووعوده.. ووروده.\nولكن هذه رواية جريمة!\nفهل سيكون اللقاء الثاني نورًا وقُبلة حياة لفدوى ووليد؟ أم سينقلب إلى نار تحرق الجميع؟\nرواية تبدأ بقتل وقصة حب.. فأين ستنتهي؟ وكيف يمكن للعدالة العمياء أن تتحقق بين أتون المشاعر المتشابكة وأسرار الماضي القاتمة؟\nنهى داود، كاتبة مصرية ولدت في إنجلترا عام 1975م، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".", "/images/products/9789777955652.webp", "9789777955652", "ذات الوشاح الوردي", null, 250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 77, "خالد منتصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعيدنا هذه الرواية إلى «زمن سعاد»، الفراشة التي ظلَّت تحلِّق بأجنحة الجمال والحب فوق أحلامنا المُجهَضة بالخوف والاستبداد والهزيمة، ولأنها لم تكف عن الطيران يومًا حتى وهي تختار طيرتها الأخيرة في تلك العاصمة الباردة، كان عليها الانسحاب مبكرًا لتنزوي في ركن من الذكريات. وبينما هي كذلك، تأتي هذه الرواية لتكون شاهدة على زمن صعود المسوخ البشرية، وأفول «زمن سعاد» الذي غابت شمسه وانطفأ بريقه بعد أن داهمه ليلٌ حالكٌ أفرخ فيه الظلام خفافيش الفتوى وسدنة التديُّن الشكلي وبيزنس توظيف الأموال، فكان لا بد لسعاد من غياب مُوجِع، وانسحاب بلا عودة، فلم يَعُد هذا زمانها، وربما لم يَعُد زماننا نحن أيضًا! ـــــــــــــــــــــــــــــــــــــــــ\nخالد منتصر، تخرَّج في كلية طب قصر العيني، وشغل منصب مدير الخدمات الصحية بهيئة قناة السويس. صدر له أكثر من عشرة كتب ومجموعة قصص قصيرة.اشتغل بالكتابة الصحفية وله عدد من المقالات المنشورة في الصحف والمجلات، وفي مجال العمل الإعلامي قدَّم برامج طبية وثقافية على عدة فضائيات.حصل على جائزة البحرين لأفضل عمود صحفي عربي في عام 2010.", "/images/products/9789777955614.webp", "9789777955614", "زمن سعاد", null, 275m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 78, "أحمد حمدان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب رحلة لم تبدأ لتصل، بل لتفتح دروبًا جديدة في بحرٍ لا ساحل له. رحلة تجول بين مدارات القانون، تغوص في أعماقه، وتستضيء بمصابيحه، لتقتنص قبسًا من نور يروي عطش العقول، ويوقظ الأرواح التائقة للمعرفة. إنّه دعوة لاكتشاف مذاقات فكرية لم يجرّبها كثيرون، ولقاء مع حقائق لم يُظن يومًا بوجودها.\nوهذا الكتاب ما هو إلا لبنة في مشروع أكبر، وسطر في سلسلة أوسع تنشد تجديد الصناعة القانونية، وبناء عقلٍ قانونيّ متوثّب، جذرُه في أصولنا الشرعية ومصالحنا المرعية، وفرعُه ممتدّ إلى فضاء الفكر الإنساني الرحب. غايته أن يزرع بذور الوعي، ويُقيم جسور الإلهام، ويُرشد الحائر، ويُلهم العاثر.\nومن رحم هذه الرؤية وُلدت مؤسسة رشد المعارف \"رشد\"، لتكون أيقونة تغيير وإلهام في فضاء القانون والمعرفة. لم تُؤسَّس لتُضاف إلى أعداد المؤسسات القائمة، بل لتكون بصمة متفرّدة، ومَعلَمًا يُهتدى به، ومشروعًا يستلهم من تراثنا الأصيل، وينفتح على تجارب الإنسانية العظمى.\nإن الإنتاج المعرفي الذي تبشّر به \"رشد\" ليس غاية مكتفية بذاتها، بل وسيلة لإعادة صياغة العقل القانوني، وبنائه على الفهم الراسخ، والوعي النافذ، والإبداع الخلّاق. هي مشاريع تحمل وعدًا لجيلٍ جديد من القانونيين؛ جيل يعبر حدود المألوف، ليؤسس لآفاقٍ يستطيع أن يكون فيها أثبتَ قَدمًا، وأبعد رؤيةً، وأعمق فهمًا.\nد.فارس بن محمد القرني", "/images/products/9789777955591.webp", "9789777955591", "أعلام التفكير القانوني", null, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 79, "هشام الخشن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالمٍ يتقاطع فيه الماضي مع ألاعيب الحاضر، خرجت قطعة صغيرة سرًّا من دار سك العملة في فيلادلفيا عام 1913، واختفت بين الأيدي تاركة أثرًا لا يلاحظه إلا القليل.\nتعاود الظهور بخيط يربط بين قصر القبة أيام فاروق وصخب القاهرة المعاصرة.\nخيط يمسك أطرافَه فريقٌ  لا يشبه بعضه بعضا:\nعباقرة، مشكّكون، وهاربون من ماضيهم. يجمعهم فقط هوس بشيء لا يعرفون إن كان حقيقة أم فخًّا متقنًا.\nرحلة أقرب إلى مطاردة بين زمنين وحكاية تغيّر شكلها كلما شارفت علي النهاية.\nويظل السؤال الحائر بلا إجابة.\nمَن يطارد مَن: الحقيقة… أم الأسطورة؟؟؟\nهشام الخشن.. روائي وقاص مصري، يعمل مهندسًا مدنيًّا. له عدد من الروايات منها: «ما وراء الأبواب»، و«تلال الأكاسيا»، و«حدث في برلين»، و«شلة ليبون»، و«ناعومي وأخواتها». تحوَّلت روايته «7 أيام في التحرير» إلى ملسلسل تلفزيوني، ووصلت روايته «جرافيت» إلى القائمة الطويلة لجائزة البوكر العربية عام 2014م. له مجموعتان قصصيتان هما: «حكايات مصرية جدًّا»، و«دويتو».", "/images/products/9789777955621.webp", "9789777955621", "نكلة فاروق", null, 185m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 80, "إبراهيم عبد المجيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا كتاب جديد لإبراهيم عبد المجيد يضم مجموعة من المقالات والدراسات الهامة التي نُشرت في صحف شهيرة بين عامي 2025-2024م. تدور حول قضايا الإنسان في العالم، والأوضاع الإنسانية في تجلياتها السياسية والاجتماعية والثقافية، وقضايا فلسفية عابرة للزمن. وكالعادة ضم إليها مراجعات لكتب هامَّة لعدد من أهم الكُتَّاب والأدباء والمفكرين من كل الأعمار. هكذا ستجد نفسك أثناء القراءة مستمتعًا برحلة فكرية وإنسانية دافقة بالمحبة، ستأخذك إلى فضاء من الجمال والأمل.\nإبراهيم عبد المجيد، كاتب وروائي مصري، له أكثر من 25 رواية، منها: ثلاثية الإسكندرية، و\"في كل أسبوع يوم جمعة\"، و\"أداجيو\"، و\"بيت الياسمين\"، و\"البلدة الأخرى\"، عرف بعضها الطريق إلى السينما والتلفزيون. له خمس مجموعات قصصية، وأكثر من خمسة عشر كتابًا بين الدراسات والمقالات والترجمة. تُرجمت بعض أعماله إلى الإنجليزية والفرنسية وغيرهما، وحاز أرقى الجوائز مثل: جائزة الشيخ زايد بالإمارات، وجائزة كتارا بقطر، وجائزة النيل بمصر.", "/images/products/9789777955638.webp", "9789777955638", "كيف تعود الى وطن لم تغادره", null, 400m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 81, "جمال سند السويدي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تزايد الاهتمام الإعلامي والعلمي بالرحم الاصطناعي في السنوات القليلة الماضية على مستوى العالم، ولا سيما مع التقدم السريع الذي تحرزه البحوث، التي تجرى في كثير من الدول، مــن الصين واليابان شرقا، إلى أوروبا وأمريكا الشمالية غرباء لاستكشاف و اختبار إمكانية حدوث حمل كامل خارج الجسد؛ أي خارج الرحم الطبيعي. وعلى الرغم من أن بحوث الرحم الاصطناعي لا تزال في مرحلة باكرة إلى حد ما، وتُجرى على الحيوانات؛ ومقيدة بقواعد أخلاقيات العلم والبحوث المتفق عليها؛ فإن التقدم المتسارع المذهل، الذي يتحقق في تلك البحوث، التي تتضافر فيها حقول معرفية وبحثية عدة خاصة الذكاء الاصطناعي والتقنية، أطلق العنان لخيال البشر للتفكير في لحظة سيتمكن فيها الإنسان من التحكم بعملية الحمل؛ لتتحقق كاملة خارج جسم الإنسان؛ وتبشر بمرحلة للتكاثر ما بعد البشري، خاصة أن تلك البحوث تستفيد من التقدم المتسارع في تقنية المعلومات، والذكاء الاصطناعي وتطبيقاته، والتطور المذهل في تصنيع الروبوتات، والتقنية المتناهية الصغر (النانو تكنولوجي)، والاندماج المتزايد بين علم الأحياء\n(البيولوجي) وعلم الحاسوب. وتكفي إطلالة سريعة على التقارير الصحفية في وسائل الإعلام بشتى اللغات؛ للوقوف على الآفاق التي وصل إليها خيال البشر؛ ومقارنتها بالحالة الفعلية الراهنة للبحوث في مجال الرحم الاصطناعي؛ إذ تنقل تقارير منشورة تقديرات للعلماء، تشير إلى أن إمكانية تطوير رحم اصطناعي، خلال الفترة المقبلة، تسهم في إنقاذ الأطفال الخدج، المولودين قبل إتمام 37 أسبوعًا في رحم الأم وهذا هو السبب الرئيسي للوفاة بين حديثي الولادة في العالم ؛ وهذا التطور المحتمل يثير - برغم محدوديته مقارنة بما يذهب إليه الخيال - تساؤلات أخلاقية بشأن مستقبل ولادة الأطفال .\nجمال سند السويدي\nمفكر وكاتب وخبير استراتيجي إماراتي، شغل منصب مدير عام مركز الإمارات للدراسات والبحوث الاستراتيجية منذ عام 1994 حتى عام 2020. ويشغل حالياً منصب نائب رئيس مجلس أمناء مركز الإمارات للدراسات والبحوث الاستراتيجية.\nشارك في عدد من المجالس الاستشارية والعلمية والتنفيذية المرموقة بصفة عضو أو رئيس، وحصل على العديد من الجوائز المحلية والدولية. تقديراً لإسهاماته وجهوده العلمية، منها جائزة الشيخ زايد للكتاب» في 1 مايو 2016، وجائزة نجيب محفوظ للآداب في 8 إبريل 2016، ولقب سفير السلام من اتحاد السلام العالمي في 21 مارس 2017 تقديراً لجهوده الكبيرة والمتواصلة في العمل على نشر ثقافة التسامح والوسطية.\nألف أكثر من 35 كتاباً من مختلف الأدبيات السياسية والاجتماعية أحدثها كتاب «الهوية الوطنية في دولة الإمارات العربية المتحدة.. بين خصوصية الثوابت والقيم وعالمية المعايير، وكتاب صاحب السمو الشيخ محمد بن زايد آل نهيان.... إضاءات في مسيرة رجل الإنسانية». وأعد وحزر عدداً آخر من الكتب القيمة، أبرزها كتاب حرب اليمن .1994.. الأسباب والنتائج، وكتاب إيران والخليج.. البحث عن الاستقرار» وكتاب أمن الخليج في القرن الحادي والعشرين».", "/images/products/9789948726050.webp", "9789948726050", "الرحم الاصطناعي", null, 350m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 82, "مصطفي عبيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه المغامرة التاريخية يفضُّ المؤلف ملفات مختومة، ويفتح سجلات مُغلقة، ويغزو مناطق محرَّمة، رافضًا كلَّ القيود التي تفرضها كلمات مثل: «ممنوع»، «سري»، و«محظور».\nيصطحب مؤلف الكتاب أدواته التاريخية للتنقيب في ملفات رجال الأمن السياسي السِّري في مصر خلال النصف الأول من القرن العشرين، راصدًا حكايات مُخبرين سريين عُتاة، استثنائيين، غاية في الذكاء والدهاء، كاشفًا عن صراعهم في لعبة الدفاع عن السلطة، ومآلات هذا الصراع. إنها سيرةٌ داميةٌ شارك فيها قتلةٌ، وأشرارٌ، وأبطالٌ، وخونةٌ، وشهدت تحولات وغرائب وفضائح وجرائم تستحق الحكي. فمن جورج فليبيدس، الشامي المتمصر الذي جمع ثروته من العمل الأمني، إلى مكفرسون، صاحب المزاج المتقلب، ومن إنجرام، الداهية الإنجليزي الرهيب، وصولًا إلى نجيب الهلباوي الخائن الغامض، ومن كيون بويد المُتغَطرِس، إلى سليم زكي المُخيف.\nأنت هنا تقرأ تاريخًا آخرَ سريًّا للسلطة في مصر المحتلة، وتتعرّف على ميراث لا يزال مسكوتًا عنه.\nمصطفى عبيد\nروائي وباحث تاريخي، يعمل بالصحافة، صدر له 25 كتابًا متنوعًا في التاريخ والأدب، وفاز بجوائز عديدة عن كتاباته، كما وصل عددٌ من مؤلفاته إلى قوائم الكتب الأكثر مبيعًا.", "/images/products/9789777955584.webp", "9789777955584", "مخبرون ومخبرون", null, 225m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 83, "كريم سليمان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«أرجوك! لا تأخذ الأمورَ على محمل شخصي.. ما رأيك لو انتظرتُ معك وأنت تقضي ساعاتك الأخيرة؟ اعتبرها تعبيرًا بسيطًا من ناحيتي بالعِرفان للفترة التي قضيتُها معكَ في عقلك..\nتَمَنَّى جلال لو كان هذا كله مجرد كابوس، لكنه كان مدركًا تمام الإدراك بأن هذه المحادثة – بالرغم من غرابة المكان – كانت حقيقية.. موتُه كان حقيقة لا مفر منها...\nمسألةُ وقت..».\nما بدأ كتحقيق سري بشأن حادثة طيران غامضة يتحول إلى مهمة انتحارية، تكشف عن أسرار لن تغير من نظرتنا إلى التاريخ الإنساني فحسب، بل وتكشف اللثام عن خطر كامن..\nخطر يهدد مصير الجنس البشري بأسره.\nكريم سليمان، مواليد القاهرة 1984، تخرَّج في كلية الصيدلة بجامعة عين شمس، وحصل على ماجيستير إدارة الأعمال بالجامعة الأمريكية بالقاهرة. بدأ مشواره الروائي بقصة قصيرة كانت جزءًا من الحملة الدعائية لـ (Sony Pictures) لفيلمهم (The 5th Wave). نشر العديد من روايات الخيال العلمي باللغة الإنجليزية، أبرزها (The Warrior's Path)، التي وصلت إلى قائمة الأكثر مبيعًا على «أمازون». و(Army of the Cursed) والتي تأهلت إلى نصف نهائي مسابقة SPFBO السنوية، التي تُدار تحت إشراف الكاتب العالمي مارك لورنس.", "/images/products/9789777955553.webp", "9789777955553", "الموت الرمادي", null, 325m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 84, "ريم جميل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نادي الفيديو\nفي التسعينيات، تستيقظ مصر على زلزال، اعتقد البعض أنه اليوم العظيم أو يوم القيامة، لكن \"يوسف\" كان مُهددًا بزلزال آخر، وهو إغلاق مشروع عمره \"جو فيديو فيلم\"، والعمل مع أبيه \"نجيب بشارة\" نقيب الزبالين.\nتابع \"جو\" تطور صناعة الأفلام، من السينما والفيديو إلى الدش والإنترنت، إلى أن وقع تحت يديه \"كليب\" لفساد مسئول كبير، وجاءته الفرصة للانتقام لأبيه، فهل سيستخدم التكنولوجيا لـ \"ينظف\" بها البلد كما فعل أبوه؟\n\"نادي الفيديو\" رواية نوستالجيا عن جيل التسعينيات، جيل آمن بحلمه وبنفسه، رأى تطورات تكنولوجية سريعة، كانت أسرع من طموحاته، لكنه استطاع أن يحقق ما يريد في النهاية.\nريم جميل، صحفية ورئيسة تحرير في التلفزيون المصري. ولدت في القاهرة عام 1987، وتخرجت في كلية إعلام قسم صحافة. \"نادي الفيديو\" هي الرواية الثانية لها، أصدرت روايتها الأولى \"اللبان السحري\" عام 2021. تعيش الكاتبة الآن بين مصر والإمارات العربية المتحدة.", "/images/products/9789777955560.webp", "9789777955560", "نادى الفيديو", null, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 85, "طارق عز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "»أُدرك في لحظة صِدْق أنها الدنيا، تلك الحسناء اللعوب التي تُغريك بكل مفاتنها حتى آخر قطرة من الكأس، فتتمسّك بتأثير خمرها للنهاية، عندما يطفئ النادل الأنوار ويهزّك بقليل من القسوة لتنصرف. عندها فقط تُدرك أن الميعاد فات، ومرَّ الليلُ بلا فائدة». *** في عمله الأدبي الثاني يراوغنا طارق بعشر قصص ممتعة. قصص قصيرة ساحرة نعيش بين سطورها حيوات متنوعة مع شخوص متباينة. أجمل ما يميز القصص هو الجمع بين متعة القص وعمق المعنى. مجموعة قصصية تغازل القلب والعقل معًا. ورغم أن الموت هو عنوان المجموعة، ولكن بنظرة متأملة نجد أن الحديث عن الموت هو في جوهره محاولة لفهم الحياة. الروائي/ عمرو حسين الحاصل على جائزة غسان كنفاني للرواية العربية 2023 ـــــــــــــــــــــــــــــــ\nطارق عز .. روائي وقاص ومترجم مصري، صانع محتوى متخصص في الكتابة والقراءة. يعمل بالطيران المدني، نُشرت له قصص قصيرة في مجموعات قصصية مشتركة، مثل \"اعترافات\"، و\"اليوم الأخير\". حاصل على جائزة أفضل قصة قصيرةiRead لعام 2021، والقائمة القصيرة لنفس الجائزة 2022. وقد صدرت له ترجمة رواية \"ينابيع واكولا \" الحاصلة على جائزة أفضل رواية قصيرة 2013، ونالت روايته الطويلة الأولى «أسفار مريم المحرمة» استحسانًا وإقبالًا جماهيريًّا واسعًا، وتصدرت قوائم الأكثر مبيعًا، وتعتبر «موت مع إيقاف التنفيذ» مجموعته القصصية الأولى.", "/images/products/9789777954556.webp", "9789777954556", "موت مع إيقاف التنفيذ", null, 190m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 86, "اشرف العشماوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية في مرحلةٍ بالغة الأهمية من تاريخ مصر المعاصر، من خلال موظف في إدارة المراسم عمل لسنوات بمعيّة الرئيسين السادات ومبارك ، فاقترب بما يكفي ليصبح شاهدًا على كواليس عصرٍ كامل؛ تكشف الرواية في واقعيةٍ مشوّقة عن مرحلة الانتقال من دهاليز المراسم إلى أروقة السلطة.. حيث تُدار الأمور في صمتٍ مُحكم، وتُحاك المؤامرات بدهاء. هذه الرواية عن إنسان عادي حين تفتك به سلطة المناصب، وتمزّقه التناقضات ويظلله الخوف. وبين قسوةٍ تربّى عليها منذ طفولته، ورقّة الموسيقى التي يُجيد عزفها على آلة الكمان، يحاول أن يجد خلاصه؛ لكن كل نغمةٍ يعزفها تغدو مِرآةً لجراحه ومرثية لأحلامه، وكل لحنٍ يؤلفه يتحوّل إلى قناعٍ يخفي وراءه خوفه العميق. \"السيمفونية الأخيرة \" رحلة تأملية جريئة إلى أعماق النفس البشرية، تضع القارىء منذ المفتتح في التجربة بكل تناقضاتها، ثم تتركه معلقًا بين الحقيقة والخيال في سيمفونية لا تنتهي من كشف الأسرار وتبدل المصائر .\nأشرف العشماوي روائي وقاضٍ مصري، نُشرت له اثنتا عشرة رواية طويلة، وكتابٌ وثائقيٌّ عن الآثار المصرية المُهربة للخارج ومحاولات استعادتها بعنوان \"سرقات مشروعة\"، وثلاث نوفيلات بعنوان \"مواليد حديقة الحيوان\". فاز بعدة جوائز محلية وعربية وعالمية، وتُرجمت أعماله إلى إحدى عشرة لغة أجنبية.", "/images/products/9789777955546.webp", "9789777955546", "السيمفونية الاخيرة", null, 275m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 87, "آمنة الغنيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أربع بنات وأربع حكايات، ما بين دانة التي تعيش مع أشباح الماضي.\nولولوة التي تغلق نفسها على سرها، ونجلاء التي تجري وراء وهم الثراء، وصبا التي تعيش داخل سجن سلبيتها.\nنعيش حكايتهن، أوجاعهن، وأفراحهن، فهل تستحق السعادة أن نكسر حاجز خوفنا وسجن أفكارنا لتحلق في سمائها ؟\nآمنة الغنيم حاصلة على شهادة علم الاجتماع والخدمة الاجتماعية من جامعة الكويت عملت باحثة اجتماعية في دار الرعاية الأحداث، ومساعد علمي في جامعة الكويت صدر لها كتاب \"الحرملك\"، وتكتب في العديد من الصحف والمجلات الكويتية.", "/images/products/9789777955508.webp", "9789777955508", "مهما كانت الأعذار", null, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 88, "إبراهيم عيسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في حقبة التسعينيات، حيث كانت الصحافة تكاد تكون  السلطة الرابعة، و الصراع فيها كاشف عن تشابك دوائر السياسة والسلطة والنفوذ وحيث خيوط شبكتها تصطاد الجميع، يأتي هذا الصحفي الشاب من عالم الريف والجامعة والبراءة غريبًا في وسط ينشب مخالبه في قلبه وشاهدًا على معارك لا ينتصر فيها إلا الألم، يكتشف الحقيقة عن تجلي العذراء في أحد أحياء القاهرة. تلك  الحقيقة التي كان يتمنى ألا يعرفها أبدًا.\n\"مريم التجلي الأخير\" رواية مثيرة للكاتب الكبير إبراهيم عيسى، تدور بين مكاتب الصحافة الصاخبة ودهاليز السياسة الغامضة، حيث لا مكان يصلح للبراءة ولا مدينة ترحب بالأبرياء، حيث يمتزج الواقع بالزيف، والإيمان بالشك، والحقيقة بالأكاذيب.\nرواية عن زمن كان كل شيء فيه قابلًا للانفجار.\nإبراهيم عيسى صحفي وروائي مصري، مواليد نوفمبر 1965. عمل صحفيًّا بمؤسسة روز اليوسف و في عام 1995 تولى رئاسة تحرير جريدة الدستور قبل مصادرتها عام 1998 ثم أعاد تأسيسها ورئاسة تحريرها عام 2004 وحتى 2010، كما تولى رئاسة تحرير جريدة التحرير في عام2011 ثم أسس ورأس تحرير جريدة المقال في 2015. حصل على جائزة جبران تويني التي يمنحها الاتحاد العالمي للصحف 2008، كما حصل على جائزة الصحافة الحرة من منظمة إنديكس العالمية 2010، وجائزة أحسن صحفي في العالم من نقابة الصحافة البريطانية عام2011. له مؤلفات روائية وسينمائية ودرامية عديدة. كسرت رواياته الحاجز التقليدي للرواية العربية فتعدى حدود الزمان و المكان، وكان من أوائل رواد الواقعية السحرية.", "/images/products/9789777955386.webp", "9789777955386", "مريم التجلى الأخير", null, 235m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 89, "محمد سلماوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قال لها: اعذريني. أردت أن أكون صادقًا معك إلى أقصى حد، فالصدق توأم الحب. أمسك بيديها الاثنتين وقال: أحبك يا عالية كما لم أحب في حياتي. اغرورقت عيناها بالدمع، وسألته: ألم تفكر في أن تلك قد تكون مجرد رغبة عابرة؟! إنك ما زلت في سن المراهقة تسيرك غريزتك، وقد تتخيل مشاعر لا وجود لها\".\n***\nآمن خالد وعالية بأن قصة حبهما مختلفة، في بدايتها وأحداثها، فكان يجب عليهما أن يتوقعا نهايتها الاستثنائية.\nبينما تسير الرواية في عالمين متوازيين غير متقاطعين، استطاع الكاتب محمد سلماوي تضفير الأزمنة ببراعة، فكأن القارئ في روايتين لكن الأحداث تتوالى في زمن واحد.\n\"زهرة النار\" تجسيد للصراع متعدد المستويات بين الثورة المتأججة في صدور الشباب، وقيود المجتمع الصارمة التي يفرضها على مَن يريدون الحياة.\nمحمد سلماوي. أحد أهم رموز الحياة الثقافية في مصر والوطن العربي، صدر له أكثر من أربعين كتابًا، ما بين رواية ومسرح وقصة قصيرة وأعمال نقدية. تُرجم العديد من أعماله إلى لغات مختلفة، منها الإنجليزية والفرنسية والهندية وغيرها. أُعيد انتخابه عدة مرات رئيسًا لاتحاد كتاب مصر، وأمينًا عامًا للاتحاد العام للأدباء والكتاب العرب. حصل على جائزة النيل في الآداب، وجائزة الدولة التقديرية، وأوسمة وجوائز دولية منها: فرنسا وإيطاليا وفلسطين.", "/images/products/9789777955379.webp", "9789777955379", "زهرة النار", null, 195m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 90, "حنان البهي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"لا أعلم لماذا كنت أتصنع الابتسام.. كنت أخشى مواجهته بدون أن أعرف السبب.. هدوؤه وثباته الانفعالي كانا يُحيراني ويُشعراني بأن هناك شيئًا غامضًا لا أعلمه عنه ولا يريد هو الإفصاح عنه\".\n***\nفي الأربعين، دار الصراع بين المثلث: رحيم، وليلى، وهند.. بين القسوة والحنان؛ القوة والضعف؛ الحب والكراهية؛ الفقد والسعادة. اختلطت النوايا بالخطط المُحكمة، ودارت صراعات التنظيم والسُّلطة التي كانت تبحث عن مبرر لخيانة العهد.\nأحيانًا تأتي الزوابع لتعصف بكياننا، وأحيانًا أخرى تُشرق الشمس لتضيء حياتنا.. ونحن ما بين هذا وذاك، نريد أن نُعيد ما فات. ولكن كيف؟ وقد أدرك القلب أنه لا يمكن العودة إلى الوراء، وأن بعض ما فات من المستحيل إعادته، ومعظم الأخطاء لن تندمل جراحها وإن زال ألمها.\nحنان البهي، كاتبة وإعلامية مصرية. تخرجت في قسم الأدب الإنجليزي بكلية الآداب. إخصائية تطوير الذات، ومدربة تحفيزية لطرق التنفس الصحيحة وإدارة الغضب. قدمت عددًا من البرامج التلفزيونية أشهرها: «فيها حاجة حلوة» و«ست الحسن»؛ وتقدم حاليًّا بودكاست على منصات التواصل الاجتماعي، عنوانه: «من النهارده»، تتحدث فيه عن تطوير الذات والتغلب على التحديات الشخصية. نُشرت مقالاتها في مجلتي «7 أيام» و«نصف الدنيا»، ولها ثلاثة أعمال إبداعية منشورة، هي: «أنا والشغالات»، و«العباية»، و«نص حالة خاصة».", "/images/products/9789777955300.webp", "9789777955300", "في الأربعين", null, 385m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 91, "شريف صالح", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"مرة ثانية التقينا في مقهى الفيشاوي. شربنا الشاي الخفيف بالنعناع. سمحتُ لنفسي أن أحضن يدها الصغيرة بين يديّ. أغمضتْ عينيها. كان في أصابعها بعض العُقل البارزة وعروق مزرقة.\nقالت بخجل:\nـ \"يدي ليست جميلة\".\nـ \"بالعكس. فيها شيء عنيد وطموح\".\nكانت كذبتي الأولى. كيف يكون في اليد شيء عنيد وطموح؟!\".\n\"مجانين أم كلثوم\" لا توثق فقط سيرة أكبر مطربة عربية، وإنما تقدم رؤيةً سرديةً مبتكرة لأغانيها التي أصبحت جزءًا من الوجدان العربي، وتأريخًا ثقافيًا للقرن العشرين في مصر.\nكما يُحسب للرواية أنها لم تتوقف عند أضلاع الأغنية الثلاثة: الشاعر والملحن والمطربة، وإنما أبرزت الضلع الرابع وهو جمهور الست، أولئك الذين صنعوا أسطورتها. وبفضلهم لا تزال موسيقاها تصدح في البيوت والشوارع والمقاهي من المحيط إلى الخليج.\nوإلى الأبد، سيظل صوتها ونسًا للمحبين والناس الطيبين؛ ينتصرون به على الحروب العبثية وبؤس الأيام.\nشريف صالح، كاتب وصحفي مصري. دكتوراه في النقد الأدبي من أكاديمية الفنون. حصل على عديد من الجوائز، منها: \"ساويرس\" عن مجموعة \"مثلث العشق\"، و\"دبي الثقافية\" عن مجموعة \"بيضة على الشاطئ\"، و\"الشارقة\" للإصدار الأول عن مسرحية \"رقصة الديك\". له نحو عشرين كتابًا، منها: رواية \"حارس الفيسبوك\" و\"ابتسامة بوذا\" و\"نجيب محفوظ وتحولات الحكاية\".", "/images/products/9789777955270.webp", "9789777955270", "مجانين أم كلثوم", null, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 92, "مينا عادل جيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه رواية الخيال الساخر، أو السخرية الخيالية.. تجذب قارئها إلى عوالم غامضة وغير معتادة، ناسفة الحدود بين الحقيقة والوهم، حول شخصية مثيرة للحيرة والارتباك، تجمع كل شيءٍ ونقيضه، فتسقط بينما تسعى إلى الرُّقي والصعود، فتعيش الواقع خيالًا، وتجلب الخيال ليتجسَّد على أرض الواقع!\nتبدأ القصة بعثور المترجم على مخطوطة نادرة مكتوبة باللغة القبطية، تحكي قصة راهب كان يعيش بين القرنين السادس والسابع الميلاديين، خاض رحلة عجائبية من نوع مصري/قبطي شديد الخصوصية والفرادة، مع بعض همسات وجودية وعبثية، ورغم أن الحماقة ربما تغلب فيها القداسة، فهي قصة تستحق أن تُروى؛ لأن قصص السقوط لا تقل أهمية عن قصص الوصول.\nمينا عادل جيِّد، كاتب وروائي ولد في صعيد مصر. تخرَّج في كلية الآداب قسم الإعلام بجامعة المنيا، ثم حصل على دبلوم الدراسات العليا في التنمية الثقافية بجامعة القاهرة. يعمل منذ سنوات في المجتمع المدني، خاصة تنمية المجتمعات الفقيرة في الصعيد. كتب في عدد من الصحف والمجلات والمواقع المصرية، وعمل مقدمًا ومُعدًّا لبرامج تلفزيونية. حصل على جائزة معرض القاهرة الدولي للكتاب عام 2021 عن كتابه «كنت طفلًا قبطيًّا في المنيا». من أعماله القصصية والروائية: «نواحي البطرخانة»، و«بيت المساكين»، و«جزيرة إلخ إلخ»، و«الأستاذ بشير الكُحلي».", "/images/products/9789777955188.webp", "9789777955188", "سقوط أوراق التين", null, 240m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 93, "طارق الطيب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سأقول لك شيئًا لا أعرف هل سيروق لك أم سيقلقك. يمكننا أن نجعلك تستمع لأدقّ أسرار الحياة السابقة وكلِّ ما مرّ حتّى يومنا هذا، لكن متى رغبت في مغادرتنا، فسنعملُ على محو كلّ المعلومات والأسرار التي عرفتها، وإلا...لن تتحمّل التنكيل الذي سيحيق بك\".\n***\nهناك على الناحية الأخرى من جسر الحياة، تقف الأبديَّةُ لتحرس سكونَ الأموات، من الآن لن يصبح العدم مخيفًا ومقبضًا.. هناك لا يلتقي الإنسان بناصره وغريمه فحسب، بل يلتقي أيضًا بنفسه، حيث ساحة \"البوح\" التي يتخفف فيها \"الضمير\" الإنساني مما يثقل روحه، لا أحد هناك يلوم الآخر على ما فعله في الحياة السابقة، فالأرواح تأتي نقيّة... في نهاية هذه الرواية \"ستشعر بعد خروجك أنّك غفوت قليلًا في مكان ما\"!\nطارق الطيب من مواليد القاهرة 1959. انتقل إلى فيينا عام 1984. له 20 كتابًا مترجمًا. حصل على وسام الجمهورية النمساوية في 2008، عُين سفيرًا ثقافيًا للنمسا في العام نفسه. صدر له مؤخرًا (ما يسبق الواو) و(لهو الإله الصغير).\nسنةالنشر :- 2025", "/images/products/9789777955218.webp", "9789777955218", "رايت ما لا يجوز لك", null, 220m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 94, "نهى داود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فجأة تتحول مدينة دهب الوادعة إلى مدينة يسكن الخوف ربوعها، بعد انتشار شائعات عن وجود قاتل يستهدف النساء، وسرعان ما يكتسب اللقب المخيف \"سفاح دهب\"!\nتبدأ القصة ببلاغ من ندى حول اختفاء صديقتها الأمريكية، وتحاول التعاون مع المقدم عاصم متجاوزة ذكرى علاقة شائكة ومؤرقة للطرفين.. وفي إطار من التشويق والإثارة تتصاعد الأحداث مع اكتشاف اختفاءات سابقة لم ينتبه إليها أحد.. ترتعد فرائص الجميع ويتساءلون مَن ستكون الضحية التالية؟ أم تنقلب الأدوار فيلاحق المجرم رموز العدالة؟\nنهى داود، كاتبة مصرية ولدت في إنجلترا عام 1975، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت في أدب الجريمة. صدر لها 9 روايات منها: \"جريمة السيدة هـ\"، و\"رضا\"، و\"جريمة العقار 47\"، و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\".", "/images/products/9789777955119.webp", "9789777955119", "ذبابة زرقاء", null, 275m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false }
                });
        }

